insert into public.tpl_geoint_referencias(codigo,nombre,tipo,region,provincia,comuna,localidad,lat,lng,prioridad,nivel_turismo,activo,fuente_id,fuente_nombre,metadata)
select d.codigo,d.nombre,d.tipo,d.region,d.provincia,d.comuna,d.localidad,d.lat,d.lng,d.prioridad,d.nivel_turismo,d.activo,f.id,'TPL National Catalog 2026-Q3',d.metadata
from datos d cross join fuente f
on conflict(codigo) do update set nombre=excluded.nombre,tipo=excluded.tipo,region=excluded.region,lat=excluded.lat,lng=excluded.lng,
 prioridad=excluded.prioridad,nivel_turismo=excluded.nivel_turismo,activo=true,fuente_id=excluded.fuente_id,metadata=excluded.metadata,updated_at=now();

