insert into public.tpl_geoint_perfiles(region,provincia,comuna,localidad,comuna_normalizada,localidad_normalizada,
 centro_comunal_id,hub_principal_id,destino_turistico_id,hub_secundario_id,turismo_reemplaza_hub,activo,geoint_version,metadata)
select d.region,d.provincia,d.comuna,d.localidad,d.comuna_norm,d.localidad_norm,
 centro.id,hub.id,dest.id,sec.id,d.reemplaza,true,'geoint-v1-centro-sur',
 jsonb_build_object('cut',d.cut,'nivel_turismo',d.turismo,'fuente','tpl_catalogo_nacional_2026q3')
from datos d
join public.tpl_geoint_referencias centro on centro.codigo=d.centro_codigo
left join public.tpl_geoint_referencias hub on hub.codigo=d.hub_codigo
left join public.tpl_geoint_referencias dest on dest.codigo=d.destino_codigo
left join public.tpl_geoint_referencias sec on sec.codigo=d.secundario_codigo
on conflict(comuna_normalizada,localidad_normalizada) do update set
 region=excluded.region,provincia=excluded.provincia,comuna=excluded.comuna,localidad=excluded.localidad,
 centro_comunal_id=excluded.centro_comunal_id,hub_principal_id=excluded.hub_principal_id,
 destino_turistico_id=excluded.destino_turistico_id,hub_secundario_id=excluded.hub_secundario_id,
 turismo_reemplaza_hub=excluded.turismo_reemplaza_hub,activo=true,geoint_version=excluded.geoint_version,
 metadata=public.tpl_geoint_perfiles.metadata||excluded.metadata,updated_at=now();

-- Alias operativo: propiedades antiguas guardan Ñipas como comuna, aunque administrativamente pertenece a Ránquil.
insert into public.tpl_geoint_perfiles(region,provincia,comuna,localidad,comuna_normalizada,localidad_normalizada,
 centro_comunal_id,hub_principal_id,destino_turistico_id,turismo_reemplaza_hub,activo,geoint_version,metadata)
select 'Ñuble','Itata','Ñipas',null,'nipas','',c.id,h.id,c.id,false,true,'geoint-v1-centro-sur',
 '{"alias_of":"Ránquil","capital_comunal":"Ñipas","nivel_turismo":"regional"}'::jsonb
from public.tpl_geoint_referencias c
join public.tpl_geoint_referencias h on h.codigo='urb_chillan'
where c.codigo='comuna_16206'
on conflict(comuna_normalizada,localidad_normalizada) do update set
 centro_comunal_id=excluded.centro_comunal_id,hub_principal_id=excluded.hub_principal_id,destino_turistico_id=excluded.destino_turistico_id,
 activo=true,geoint_version=excluded.geoint_version,metadata=public.tpl_geoint_perfiles.metadata||excluded.metadata,updated_at=now();

-- Excepción turística: Caburgua usa Pucón/Eje Lacustre como hub efectivo; Temuco queda implícito como referencia regional futura.
insert into public.tpl_geoint_perfiles(region,provincia,comuna,localidad,comuna_normalizada,localidad_normalizada,
 centro_comunal_id,hub_principal_id,destino_turistico_id,turismo_reemplaza_hub,activo,geoint_version,metadata)
select 'La Araucanía','Cautín','Pucón','Caburgua','pucon','caburgua',c.id,h.id,h.id,true,true,'geoint-v1-centro-sur',
 '{"nivel_turismo":"internacional","regla":"destino_turistico_reemplaza_hub"}'::jsonb
from public.tpl_geoint_referencias c
join public.tpl_geoint_referencias h on h.codigo='urb_villarrica_pucon'
where c.codigo='comuna_09115'
on conflict(comuna_normalizada,localidad_normalizada) do update set
 centro_comunal_id=excluded.centro_comunal_id,hub_principal_id=excluded.hub_principal_id,destino_turistico_id=excluded.destino_turistico_id,
 turismo_reemplaza_hub=true,activo=true,geoint_version=excluded.geoint_version,metadata=public.tpl_geoint_perfiles.metadata||excluded.metadata,updated_at=now();

create or replace function public.tpl_geoint_auditoria_atlas_v1()
returns jsonb language sql stable security definer set search_path=public as $$
 select jsonb_build_object(
 'generado_at',now(),
 'comunas_con_coordenadas',(select count(*) from public.tpl_geoint_comunas where activo and capital_lat is not null and capital_lng is not null),
 'referencias_activas',(select count(*) from public.tpl_geoint_referencias where activo),
 'centros_comunales',(select count(*) from public.tpl_geoint_referencias where activo and tipo='centro_comunal'),
 'hubs',(select count(*) from public.tpl_geoint_referencias where activo and tipo like 'hub_%'),
 'perfiles_activos',(select count(*) from public.tpl_geoint_perfiles where activo),
 'perfiles_turismo_reemplaza_hub',(select count(*) from public.tpl_geoint_perfiles where activo and turismo_reemplaza_hub)
 );
$$;
grant execute on function public.tpl_geoint_auditoria_atlas_v1() to authenticated,service_role;
